<template>
 <main class="app-container simple-admin">
  <header><div><h1>{{meta.title}}</h1><p>{{pageHint}}</p></div><el-button :loading="loading" @click="load">刷新</el-button></header>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <template v-if="resource==='dashboard'">
   <div class="stats"><el-card v-for="item in dashboardStats" :key="item.key" shadow="never"><span>{{item.label}}</span><strong>{{item.key==='revenue'?'¥':''}}{{item.key==='revenue'?Number(data[item.key]||0).toFixed(2):data[item.key]||0}}</strong></el-card></div>
   <el-card shadow="never"><h2>常用操作</h2><div class="quick-actions"><el-button type="primary" size="large" @click="goMenu('订单管理')">处理订单</el-button><el-button size="large" @click="goMenu('预约管理')">查看预约</el-button><el-button size="large" @click="goMenu('商品管理')">管理商品</el-button><el-button size="large" @click="goMenu('会员管理')">查看会员</el-button></div><p class="help">先上架商品，顾客就能在商城购买；订单、预约和礼品记录会自动显示在对应菜单。</p><el-alert title="微信支付尚未接入，用户下单后保持待付款；接入微信支付后再启用真实收款。" type="info" :closable="false"/></el-card>
  </template>
  <el-card v-else-if="resource==='config'" shadow="never">
   <el-tabs v-model="configTab"><el-tab-pane label="店铺设置" name="basic"/><el-tab-pane label="首页图片" name="home"/><el-tab-pane label="其他页面图片" name="images"/><el-tab-pane label="协议说明" name="rules"/></el-tabs><el-alert v-if="configTab==='home'" title="首页保留绿色外框；这里只替换外框内的品牌图片，不会改变品牌名称。当前品牌：暨美丽（JI MEI LI）。" type="info" :closable="false" class="config-note"/><el-card shadow="never" class="module-manager"><div class="module-toolbar"><div><h2>首页内容模块</h2><p class="help">配置 Banner、分类入口、推荐商品、活动和公告，保存后用户端重新打开首页即可更新。</p></div><el-button type="primary" @click="editModule()">添加首页模块</el-button></div><el-table :data="homeModules" stripe empty-text="暂无首页模块，请先添加"><el-table-column label="图片" width="110"><template #default="{row}"><el-image v-if="row.image" :src="row.image" fit="cover" class="module-picture" :preview-src-list="[row.image]" preview-teleported/></template></el-table-column><el-table-column prop="title" label="标题" min-width="160"/><el-table-column prop="type" label="类型" width="110"><template #default="{row}">{{moduleTypeLabel(row.type)}}</template></el-table-column><el-table-column prop="sort" label="排序" width="80"/><el-table-column label="发布/显示" width="110"><template #default="{row}"><el-tag :type="row.publishStatus==='draft'?'warning':row.enabled===false?'info':'success'">{{row.publishStatus==='draft'?'草稿':row.enabled===false?'隐藏':'已发布'}}</el-tag></template></el-table-column><el-table-column label="操作" width="240"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">预览</el-button><el-button link type="primary" @click="editModule(row)">修改</el-button><el-button link @click="toggleModule(row)">{{row.enabled===false?'显示':'隐藏'}}</el-button><el-button link type="danger" @click="removeModule(row)">删除</el-button></template></el-table-column></el-table></el-card><el-card shadow="never" class="asset-manager"><div class="module-toolbar"><div><h2>已上传图片</h2><p class="help">未被商品、门店、活动或首页模块引用的图片才可以删除。</p></div><el-button @click="loadAssets">刷新</el-button></div><el-table :data="assets" stripe empty-text="暂无上传图片"><el-table-column label="预览" width="110"><template #default="{row}"><el-image :src="row.url" fit="contain" class="module-picture" :preview-src-list="[row.url]" preview-teleported/></template></el-table-column><el-table-column prop="originalName" label="文件名" min-width="180" show-overflow-tooltip/><el-table-column prop="createdAt" label="上传时间" width="180"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="danger" @click="removeAsset(row)">删除</el-button></template></el-table-column></el-table></el-card>
   <el-form label-position="top" class="settings-form"><el-form-item v-for="f in shownConfig" :key="f.key" :label="f.label"><el-input-number v-if="f.type==='number'" v-model="data[f.key]" :min="1" :max="10000"/><el-switch v-else-if="f.type==='bool'" v-model="data[f.key]" active-text="开启" inactive-text="关闭"/><div v-else-if="f.type==='image'" class="picture-field"><el-image v-if="data[f.key]" :src="data[f.key]" fit="contain" :preview-src-list="[data[f.key]]" preview-teleported/><el-button :loading="uploading" @click="pickImage(data,f.key)">{{data[f.key]?'更换图片':'上传图片'}}</el-button></div><el-input v-else v-model="data[f.key]" :type="f.type==='text'?'textarea':'text'" :rows="6" :placeholder="'请填写'+f.label"/></el-form-item><el-button v-if="canEdit" type="primary" :loading="saving" :disabled="uploading" @click="saveConfig">保存修改</el-button><p class="help">保存后，顾客重新打开页面即可看到更新。</p></el-form>
  </el-card>
  <el-card v-else shadow="never">
   <div class="toolbar"><el-input v-model="keyword" :placeholder="searchHint" clearable class="search"/><el-select v-if="statusOptions.length" v-model="status" clearable placeholder="全部状态" style="width:155px"><el-option v-for="item in statusOptions" :key="item.value" :value="item.value" :label="item.label"/></el-select><el-select v-if="resource==='products'" v-model="categoryFilter" clearable placeholder="按商品分类" style="width:180px"><el-option v-for="category in refs.categories||[]" :key="category.id" :value="category.id" :label="category.name"/></el-select><el-input v-if="resource==='products'" v-model="priceMin" placeholder="最低价（元）" clearable style="width:130px"/><el-input v-if="resource==='products'" v-model="priceMax" placeholder="最高价（元）" clearable style="width:130px"/><el-date-picker v-if="['products','orders','appointments','claims','shares','users','addresses','stores','categories','activities','alliances','homeModules','audit','paymentAudits','earnings'].includes(resource)" v-model="dateFrom" type="date" value-format="YYYY-MM-DD" placeholder="开始日期" clearable style="width:145px"/><el-date-picker v-if="['products','orders','appointments','claims','shares','users','addresses','stores','categories','activities','alliances','homeModules','audit','paymentAudits','earnings'].includes(resource)" v-model="dateTo" type="date" value-format="YYYY-MM-DD" placeholder="结束日期" clearable style="width:145px"/><el-button v-if="resource==='products'" @click="categoryDialog=true">商城分类</el-button><el-button @click="resetFilters">重置筛选</el-button><el-button v-if="meta.editable&&canEdit" type="primary" @click="edit()">添加{{singular}}</el-button><el-button v-if="rows.length" @click="exportCsv">导出筛选结果</el-button></div><div v-if="resource==='products'" class="batch-toolbar"><span>已选择 {{selectedRows.length}} 件商品</span><el-button size="small" :disabled="!selectedRows.length" @click="batchProducts('publish')">批量上架</el-button><el-button size="small" :disabled="!selectedRows.length" @click="batchProducts('offline')">批量下架</el-button><el-button size="small" :disabled="!selectedRows.length" @click="batchProducts('addGroup')">批量添加分组</el-button><el-button size="small" :disabled="!selectedRows.length" @click="batchProducts('removeGroup')">批量移除分组</el-button><el-button size="small" :disabled="!selectedRows.length" @click="batchProducts('memberPrice')">批量设置会员价</el-button><el-button size="small" :disabled="!selectedRows.length" @click="batchProducts('freeShipping')">批量设置包邮</el-button><el-button size="small" @click="clearSelection">清空选择</el-button></div>   <el-alert v-if="resource==='products'" class="product-feature-note" title="商品管理已支持：商城分类、商品图片、轮播图、SKU 规格、独立价格库存、上下架和首页推荐。" type="info" :closable="false" show-icon/>
   <el-table ref="tableRef" :data="pageRows" v-loading="loading" row-key="id" stripe empty-text="暂无记录" @row-dblclick="showDetail" @selection-change="onSelectionChange"><el-table-column v-if="resource==='products'" type="selection" width="48"/>
    <el-table-column v-for="col in columns" :key="col.key" :label="col.label" :min-width="columnWidth(col)" show-overflow-tooltip><template #default="{row}"><el-image v-if="col.type==='image'&&row[col.key]" :src="row[col.key]" :preview-src-list="[row[col.key]]" preview-teleported fit="cover" class="table-picture"/><el-tag v-else-if="['status','enabled','disabled','invited'].includes(col.key)" :type="tagType(row,col.key)">{{display(row,col.key)}}</el-tag><span v-else>{{display(row,col.key)}}</span></template></el-table-column>
    <el-table-column label="操作" fixed="right" :width="resource==='orders'?270:resource==='users'?245:resource==='products'?245:205"><template #default="{row}"><div class="row-actions"><el-button link type="primary" @click="showDetail(row)">查看详情</el-button><template v-if="canEdit"><el-button v-if="meta.editable" link type="primary" @click="edit(row)">修改</el-button><el-button v-if="meta.editable" link @click="copyRow(row)">复制</el-button><el-button v-if="meta.editable" link @click="update(row,{enabled:!row.enabled})">{{row.enabled?'下架':'上架'}}</el-button><el-button v-if="resource==='products'&&meta.editable" link type="warning" @click="openInventory(row)">库存调整</el-button><el-button v-if="meta.editable&&['stores','categories','products','activities','alliances'].includes(resource)" link type="danger" @click="remove(row)">删除</el-button>
     <template v-if="resource==='orders'"><el-button v-if="row.status==='pending'" link type="warning" @click="orderAction(row,'confirmPayment')">确认已收款</el-button><el-button v-if="row.status==='pending'" link type="danger" @click="orderAction(row,'cancel')">取消订单</el-button><el-button v-if="row.status==='shipping'" link type="primary" @click="orderAction(row,'ship')">填写发货信息</el-button><el-button v-if="!row.package&&['ready','shipping'].includes(row.status)" link type="success" @click="setStatus(row,'completed')">{{row.status==='shipping'?'确认已交付':'确认服务完成'}}</el-button><el-button v-if="['ready','shipping','completed'].includes(row.status)&&row.refundStatus!=='refunded'" link type="danger" @click="orderAction(row,'refund')">售后退款</el-button></template>
     <template v-if="resource==='appointments'&&row.status==='booked'"><el-button link type="success" @click="setStatus(row,'completed')">完成服务</el-button><el-button link type="danger" @click="setStatus(row,'cancelled')">取消预约</el-button></template>
     <template v-if="resource==='users'"><el-dropdown trigger="click" @command="cmd=>memberMore(row,cmd)"><el-button link>更多操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="gift">{{row.invited?'取消领礼资格':'允许领取礼品'}}</el-dropdown-item><el-dropdown-item command="points">调整积分</el-dropdown-item><el-dropdown-item command="disabled">{{row.disabled?'恢复账号':'停用账号'}}</el-dropdown-item><el-dropdown-item command="password">重置会员密码</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template>
     <el-button v-if="resource==='claims'&&row.status!=='completed'" link type="success" @click="setStatus(row,'completed')">确认已发放</el-button>
    </template></div></template></el-table-column>
   </el-table><el-pagination v-if="filtered.length" v-model:current-page="page" :page-size="15" :total="filtered.length" layout="total, prev, pager, next"/>
  </el-card>
  <el-dialog v-model="categoryDialog" title="商城分类" width="620px" destroy-on-close><div class="category-help">分类会同步到用户端商城左侧目录；商品编辑时可选择所属分类。</div><el-table :data="refs.categories||[]" size="small" border><el-table-column prop="name" label="分类名称"/><el-table-column prop="sort" label="排序" width="90"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled===false?'info':'success'">{{row.enabled===false?'已下架':'已上架'}}</el-tag></template></el-table-column><el-table-column label="操作" width="190"><template #default="{row}"><el-button link type="primary" @click="editCategory(row)">修改</el-button><el-button link @click="toggleCategory(row)">{{row.enabled===false?'上架':'下架'}}</el-button><el-button link type="danger" @click="removeCategory(row)">删除</el-button></template></el-table-column></el-table><el-form :model="categoryForm" inline class="category-form"><el-form-item label="名称"><el-input v-model="categoryForm.name" placeholder="如：特色项目"/></el-form-item><el-form-item label="排序"><el-input-number v-model="categoryForm.sort" :min="0" :precision="0"/></el-form-item><el-button type="primary" :loading="categorySaving" @click="saveCategory">{{categoryForm.id?'保存修改':'添加分类'}}</el-button><el-button v-if="categoryForm.id" @click="resetCategory">取消编辑</el-button></el-form></el-dialog>
  <el-dialog v-model="dialog" :title="(form.id?'修改':'添加')+singular" width="650px" destroy-on-close><el-form label-position="top" class="edit-form">
   <el-form-item v-for="f in shownFields" :key="f.key" :class="{'form-wide':['image','text','kind'].includes(f.type)||f.key==='name'}" :label="fieldLabel(f)" :required="f.required">
    <el-input-number v-if="f.type==='number'" v-model="form[f.key]" :min="f.key==='appointmentDurationMinutes'?15:0" :max="f.key==='appointmentDurationMinutes'?480:undefined" :precision="['price','memberPrice','referencePrice','coursePrice'].includes(f.key)?2:0" :disabled="resource==='products'&&f.key==='stock'&&!!form.skus?.length"/>
    <el-switch v-else-if="f.type==='bool'" v-model="form[f.key]" active-text="是" inactive-text="否"/>
    <el-radio-group v-else-if="f.type==='kind'" v-model="form[f.key]"><el-radio value="service">到店服务</el-radio><el-radio value="goods">实物商品</el-radio></el-radio-group><el-select v-else-if="f.type==='productStatus'" v-model="form.status" style="width:100%"><el-option value="draft" label="草稿"/><el-option value="published" label="已上架"/><el-option value="offline" label="已下架"/></el-select>
    <div v-else-if="f.type==='image'" class="picture-field"><el-image v-if="form[f.key]" :src="form[f.key]" fit="contain" :preview-src-list="[form[f.key]]" preview-teleported/><el-button :loading="uploading" @click="pickImage(form,f.key)">{{form[f.key]?'更换图片':'上传图片'}}</el-button><span class="help">选择手机或电脑中的图片即可</span></div>
    <el-select v-else-if="f.type==='product'" v-model="form[f.key]" clearable filterable placeholder="选择关联商品" style="width:100%"><el-option v-for="product in refs.products||[]" :key="product.id" :label="product.name" :value="product.id"/></el-select><el-select v-else-if="f.type==='category'" v-model="form[f.key]" clearable filterable placeholder="选择商品分类" style="width:100%"><el-option v-for="category in refs.categories||[]" :key="category.id" :label="category.name" :value="category.id"/></el-select>
    <el-date-picker v-else-if="f.type==='date'" v-model="form[f.key]" type="date" value-format="YYYY-MM-DD" placeholder="选择日期" style="width:100%"/>
    <el-input v-else v-model="form[f.key]" :type="f.type==='text'?'textarea':'text'" :rows="4" :placeholder="'请填写'+fieldLabel(f)"/>
   </el-form-item>
   <template v-if="resource==='products'&&form.kind==='service'&&!form.packagePlans?.length"><el-form-item label="是否提供疗程套餐"><el-switch v-model="courseEnabled" active-text="提供" inactive-text="不提供"/></el-form-item><el-form-item v-if="courseEnabled" label="整个疗程的价格（元）" required><el-input-number v-model="form.coursePrice" :min="0" :precision="2"/></el-form-item></template><template v-if="resource==='products'"><el-form-item label="关键词" class="form-wide"><el-input v-model="form.keywordsText" placeholder="多个关键词用空格或逗号分隔"/></el-form-item><el-form-item label="轮播图" class="form-wide"><div class="gallery-editor"><div v-for="(url,index) in (form.gallery||[])" :key="url+index" class="gallery-item"><el-image :src="url" fit="cover"/><el-button circle size="small" type="danger" @click="removeGallery(index)">×</el-button></div><el-button @click="pickImages(form,'gallery')">添加轮播图</el-button></div></el-form-item><el-form-item v-if="!form.packagePlans?.length" label="规格与 SKU" class="form-wide"><div class="sku-editor"><div v-for="(sku,index) in (form.skus||[])" :key="sku.id||index" class="sku-row"><el-input v-model="sku.name" placeholder="规格名称，如：标准装"/><el-input v-model="sku.code" placeholder="SKU 编码"/><el-input v-model="sku.attributesText" placeholder="属性，如 颜色:白,容量:30ml"/><el-input-number v-model="sku.price" :min="0" :precision="2" controls-position="right"/><el-input-number v-model="sku.stock" :min="0" :precision="0" controls-position="right"/><div class="sku-image"><el-image v-if="sku.image" :src="sku.image" fit="cover"/><el-button size="small" @click="pickImage(sku,'image')">{{sku.image?'换图':'规格图'}}</el-button></div><el-switch v-model="sku.enabled" active-text="启用"/><el-button circle size="small" type="danger" @click="removeSku(index)">×</el-button></div><el-button @click="addSku">添加规格</el-button><p class="help">每个规格可独立设置价格、库存、编码和图片；未添加规格时使用商品单价和库存。</p></div></el-form-item></template>
   <package-editor v-if="resource==='products'&&form.packagePlans?.length" class="form-wide" :plans="form.packagePlans"/>
   <p v-if="resource==='products'&&form.trialOnly" class="help form-wide">项目展示价值用于体验卡说明，领取和预约无需支付。可在副标题填写体验范围，如“单部位”。</p><el-button v-if="resource==='products'" class="form-wide" link type="primary" @click="advanced=!advanced">{{advanced?'收起更多设置':'更多设置：首页推荐、礼品和商品介绍'}}</el-button><p v-if="resource==='products'" class="help form-wide">价格修改后立即用于新订单。若商品图片中也写了价格，请同时更换图片。</p>
  </el-form><template #footer><el-button @click="dialog=false">暂不修改</el-button><el-button type="primary" :loading="saving" :disabled="uploading" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="inventoryDialog" title="库存调整" width="520px" destroy-on-close><el-form label-position="top"><el-form-item label="商品"><el-input :model-value="inventoryProduct?.name||''" disabled/></el-form-item><el-form-item v-if="(inventoryProduct?.skus||[]).length" label="SKU" required><el-select v-model="inventoryForm.skuId" filterable style="width:100%"><el-option v-for="sku in inventoryProduct.skus" :key="sku.id" :value="sku.id" :label="(sku.name||'默认规格')+' · 库存 '+sku.stock"/></el-select></el-form-item><el-form-item label="变动数量" required><el-input-number v-model="inventoryForm.delta" :min="-1000000" :max="1000000" :precision="0"/></el-form-item><el-form-item label="调整原因" required><el-input v-model="inventoryForm.reason" placeholder="例如：盘点修正、入库补货、损耗扣减" maxlength="200" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="inventoryDialog=false">取消</el-button><el-button type="primary" :loading="inventorySaving" @click="saveInventory">保存调整</el-button></template></el-dialog>
  <el-dialog v-model="moduleDialog" title="首页内容模块" width="620px" destroy-on-close><el-form label-position="top"><el-form-item label="模块类型" required><el-select v-model="moduleForm.type" style="width:100%"><el-option value="banner" label="Banner"/><el-option value="category" label="分类入口"/><el-option value="product" label="推荐商品"/><el-option value="activity" label="活动入口"/><el-option value="store" label="门店入口"/><el-option value="notice" label="公告/图文"/></el-select></el-form-item><el-form-item label="标题" required><el-input v-model="moduleForm.title" placeholder="例如：春季焕新活动"/></el-form-item><el-form-item label="副标题"><el-input v-model="moduleForm.subtitle" placeholder="可选"/></el-form-item><el-form-item label="图片" required><div class="picture-field"><el-image v-if="moduleForm.image" :src="moduleForm.image" fit="contain"/><el-button @click="pickImage(moduleForm,'image')">{{moduleForm.image?'更换图片':'上传图片'}}</el-button></div></el-form-item><el-form-item label="跳转类型"><el-select v-model="moduleForm.targetType" clearable style="width:100%" @change="moduleForm.targetId=''" ><el-option value="product" label="商品"/><el-option value="category" label="分类"/><el-option value="activity" label="活动"/><el-option value="store" label="门店"/></el-select></el-form-item><el-form-item v-if="moduleForm.targetType" label="跳转目标"><el-select v-model="moduleForm.targetId" filterable clearable style="width:100%" placeholder="搜索并选择目标"><el-option v-for="option in moduleTargetOptions" :key="option.id" :label="option.name" :value="option.id"/></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="moduleForm.sort" :min="0" :precision="0"/></el-form-item><el-form-item label="发布状态"><el-select v-model="moduleForm.publishStatus" style="width:100%"><el-option value="draft" label="保存为草稿"/><el-option value="published" label="立即发布"/></el-select></el-form-item><el-form-item label="显示"><el-switch v-model="moduleForm.enabled" active-text="显示" inactive-text="隐藏"/></el-form-item><el-form-item label="说明"><el-input v-model="moduleForm.description" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="moduleDialog=false">取消</el-button><el-button type="primary" :loading="moduleSaving" @click="saveModule">保存</el-button></template></el-dialog>
  <el-drawer :model-value="!!detail" :title="singular+'详情'" size="580px" @close="detail=null"><template v-if="detail"><el-image v-if="detail.image||detail.avatar||detail.product?.image" :src="detail.image||detail.avatar||detail.product.image" fit="contain" class="detail-picture"/><el-descriptions :column="1" border><el-descriptions-item v-for="key in shownDetails" :key="key" :label="detailLabel(key)">{{display(detail,key)}}</el-descriptions-item></el-descriptions><template v-if="detail.package"><h3>{{detail.package.planName}} · 套餐服务</h3><p class="help">在预约管理中逐次完成服务，全部次数用完后订单自动完成。</p><el-table :data="detail.package.services"><el-table-column prop="name" label="项目" min-width="180"/><el-table-column prop="total" label="总次数" width="80"/><el-table-column prop="used" label="已核销" width="80"/></el-table></template><package-editor v-if="detail.packagePlans?.length" :key="detail.id" :plans="detail.packagePlans" readonly/></template></el-drawer>
 </main>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import PackageEditor from './PackageEditor.vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import useUserStore from '@/store/modules/user'
import {schemas,configFields,labels} from './schema'
import {statusNames,formatBusiness,detailFields} from './presentation'
const props=defineProps({resource:{type:String,default:'dashboard'}})
const resource=computed(()=>props.resource),meta=computed(()=>schemas[props.resource]||schemas.dashboard)
const router=useRouter()
const tableRef=ref(null),data=ref({}),rows=ref([]),refs=ref({}),homeModules=ref([]),assets=ref([]),keyword=ref(''),status=ref(''),page=ref(1),loading=ref(false),saving=ref(false),uploading=ref(false),error=ref(''),dialog=ref(false),form=ref({}),detail=ref(null),courseEnabled=ref(false),configTab=ref('home'),advanced=ref(false),categoryFilter=ref(''),priceMin=ref(''),priceMax=ref(''),dateFrom=ref(''),dateTo=ref(''),selectedRows=ref([]),categoryDialog=ref(false),categoryForm=ref({name:'',sort:1,enabled:true}),categorySaving=ref(false),moduleDialog=ref(false),moduleSaving=ref(false),moduleForm=ref({type:'banner',title:'',subtitle:'',image:'',sort:1,enabled:true,publishStatus:'draft',targetType:'',targetId:'',description:''}),inventoryDialog=ref(false),inventorySaving=ref(false),inventoryProduct=ref(null),inventoryForm=ref({productId:'',skuId:'',delta:0,reason:''})
const singular=computed(()=>({products:'商品',categories:'分类',stores:'门店',users:'会员',orders:'订单',appointments:'预约',claims:'礼品领取记录',activities:'活动',alliances:'合作商家',shares:'邀请记录', rewards:'积分商品', ledger:'积分流水', redemptions:'兑换记录'}[resource.value]||meta.value.title))
const pageHint=computed(()=>({dashboard:'今天的经营情况和常用操作',products:'添加商品、修改价格，或选择是否在商城上架。',stores:'每家门店单独添加，分别填写分店名称、详细地址和联系电话。保存后，顾客可查看各店地址并选择门店下单或预约。',orders:'核实收款后处理订单，服务结束或交付商品后确认完成。',appointments:'查看顾客预约，服务结束后点击“完成服务”。',users:'查看会员信息、联系电话和礼品资格。',config:'先在“首页图片”替换首页内框图片，上传后点击保存；店铺素材和基础设置在店铺设置中管理。',claims:'核实会员领取信息，交付礼品后点击“确认已发放”。'}[resource.value]||meta.value.desc))
const searchHint=computed(()=>resource.value==='products'?'搜索商品名称、商品编码、SKU编码或颜色':resource.value==='orders'?'搜索订单号、会员姓名、手机号或商品':resource.value==='users'?'搜索会员姓名或联系电话':resource.value==='appointments'?'搜索会员姓名、联系电话或门店':resource.value==='shares'?'搜索邀请人、被邀请人或联系电话':resource.value==='activities'?'搜索活动名称或说明':'搜索名称、会员或关联记录')
const allowed=permission=>{const p=useUserStore().permissions;return p.includes('*:*:*')||p.includes(permission)}
const canEdit=computed(()=>allowed('anqi:'+resource.value+':edit'))
const endpoint=()=>'/anqi/'+resource.value
const dashboardStats=[{key:'users',label:'会员人数'},{key:'orders',label:'订单数量'},{key:'revenue',label:'已收款金额'},{key:'appointments',label:'预约数量'}]
const statusOptions=computed(()=>({products:['draft','published','offline'],orders:['pending','ready','shipping','completed','aftersale','cancelled'],appointments:['booked','completed','cancelled'],users:['normal','disabled','invited','notInvited'],claims:['awaiting','completed']}[resource.value]||[]).map(value=>({value,label:{normal:'正常使用',disabled:'已停用',invited:'可以领取礼品',notInvited:'不可领取礼品'}[value]||statusNames[value]||'待发放'})))
const columns=computed(()=>meta.value.cols||[])
const moduleTargetOptions=computed(()=>({product:refs.value.products||[],category:refs.value.categories||[],activity:refs.value.activities||[],store:refs.value.stores||[]}[moduleForm.value.targetType]||[]))
const shownConfig=computed(()=>configFields.filter(f=>configTab.value==='home'?['homeImage','heroTop','heroBottom','storeDefaultImage','brandLogo','welcome'].includes(f.key):configTab.value==='images'?f.type==='image'&&!['homeImage','brandLogo','welcome'].includes(f.key):configTab.value==='rules'?f.type==='text':!['image','text'].includes(f.type)))
const shownFields=computed(()=>(meta.value.fields||[]).filter(f=>!(resource.value==='products'&&form.value.packagePlans?.length&&['kind','gift','trial','trialOnly'].includes(f.key))&&!['coursePrice','sold','gallery','skus','keywords'].includes(f.key)&&(resource.value!=='products'||advanced.value||!['home','gift','trial','description','recommended','hot','isNew'].includes(f.key))))
const shownDetails=computed(()=>(detailFields[resource.value]||[]).filter(k=>!['paidAt','completedAt','paymentNote','tracking','coursePrice'].includes(k)||detail.value?.[k]!=null))
const filtered=computed(()=>rows.value.filter(r=>{const skuText=(r.skus||[]).map(s=>[s.code,s.name,Object.entries(s.attributes||{}).flat()].flat().join(' ')).join(' ');const price=Number(r.price||0);const date=String(r.createdAt||r.appointmentTime||r.date||'').slice(0,10);const member=(refs.value.users||[]).find(u=>u.id===r.userId);const textValue=[...columns.value.map(c=>display(r,c.key)),skuText,r.phone||'',r.name||'',r.number||'',r.orderId||'',r.product||'',r.productId||'',member?.name||'',member?.phone||'',r.address?.phone||''].join(' ').toLowerCase();return (resource.value!=='products'||!categoryFilter.value||r.categoryId===categoryFilter.value)&&(!status.value||(status.value==='awaiting'?!r.status||r.status!=='completed':status.value==='normal'?!r.disabled:status.value==='disabled'?r.disabled:status.value==='invited'?r.invited:status.value==='notInvited'?!r.invited:r.status===status.value))&&(!priceMin.value||price>=Number(priceMin.value))&&(!priceMax.value||price<=Number(priceMax.value))&&(!dateFrom.value||date>=dateFrom.value)&&(!dateTo.value||date<=dateTo.value)&&(!keyword.value||textValue.includes(keyword.value.toLowerCase()))}).sort((a,b)=>String(b.createdAt||b.appointmentTime||b.date||'').localeCompare(String(a.createdAt||a.appointmentTime||a.date||''))))
const pageRows=computed(()=>filtered.value.slice((page.value-1)*15,page.value*15))
let loadSequence=0
async function load(){const seq=++loadSequence;loading.value=true;error.value='';try{const r=await request({url:endpoint()});if(seq!==loadSequence)return;if(Array.isArray(r.data))rows.value=r.data;else data.value=r.data||{};const related=[];if(['orders','appointments','claims','shares','addresses','earnings','paymentAudits'].includes(resource.value))related.push('users');if(['orders','appointments'].includes(resource.value))related.push('stores');if(resource.value==='appointments')related.push('orders');if(['claims','activities'].includes(resource.value))related.push('products');if(resource.value==='products')related.push('categories');if(resource.value==='config')related.push('products','categories','activities','stores');await Promise.all([...new Set(related)].filter(k=>allowed('anqi:'+k+':list')).map(async k=>{const r=await request({url:'/anqi/'+k});refs.value[k]=r.data||[]}));if(resource.value==='config'){await loadHomeModules();await loadAssets()}}catch(e){error.value=e?.response?.data?.msg||e?.message||'暂时无法加载，请点击刷新重试'}finally{if(seq===loadSequence)loading.value=false}}
watch(resource,()=>{keyword.value='';status.value='';categoryFilter.value='';priceMin.value='';priceMax.value='';dateFrom.value='';dateTo.value='';selectedRows.value=[];page.value=1;detail.value=null;load()},{immediate:true});watch([keyword,status,categoryFilter,priceMin,priceMax,dateFrom,dateTo],()=>page.value=1)
function display(row,key){if(key==='address'&&typeof row[key]==='string')return row[key];if(key==='lastSign'&&row.lastSignAt)return formatBusiness(row,'lastSignAt',refs.value);return formatBusiness(row,key,refs.value)}
function goMenu(title){const route=router.getRoutes().find(r=>r.meta?.title===title&&r.path.includes('/anqi/'));if(route)router.push(route.path);else ElMessage.warning('当前账号没有'+title+'菜单权限')}
function columnWidth(c){if(['createdAt','paidAt','appointmentTime'].includes(c.key))return 175;if(c.width)return c.key==='image'?78:c.width;if(['name','product','productIds'].includes(c.key))return 145;if(c.key==='userId')return 125;if(['description','address','detail'].includes(c.key))return 175;if(['price','referencePrice','coursePrice','total','amount'].includes(c.key))return 92;if(['stock','sold','quantity','sort'].includes(c.key))return 78;return 92}
function detailLabel(k){if(resource.value==='stores'&&k==='address')return '门店地址';return {storeId:'服务门店',orderId:'关联订单号',product:'购买商品',productIds:'领取商品',userId:'会员姓名',spec:'购买规格',price:'购买单价'}[k]||labels[k]||'说明'}
function fieldLabel(f){return {name:singular.value+'名称',code:'商品编码（用于搜索和对账）',subtitle:'商品副标题（如：单部位）',referencePrice:'项目展示价值（元）',brand:'品牌',groupIds:'商品分组（多个分组用逗号分隔）',keywords:'关键词',categoryId:'所属分类',sort:'排序',price:form.value.packagePlans?.length?'整套售价（元）':form.value.kind==='service'?'单次服务价格（元）':'商品价格（元）',stock:'库存数量（添加 SKU 后按各规格库存合计）',status:'商品状态',home:'是否在首页推荐',recommended:'推荐商品',hot:'热销商品',isNew:'新品商品',gift:'是否可作为贵宾礼品',trial:'是否可作为体验礼品',enabled:'是否上架',freeShipping:'是否包邮'}[f.key]||f.label}
function tagType(r,k){if(k==='disabled')return r.disabled?'danger':'success';if(k==='status'){if(['published','completed'].includes(r.status))return 'success';if(['draft','pending','shipping','ready'].includes(r.status))return 'warning';if(['offline','cancelled','aftersale'].includes(r.status))return 'info';return 'warning'}return r[k]?'success':'info'}
function showDetail(row){detail.value=row}
function onSelectionChange(value){selectedRows.value=value}
function clearSelection(){selectedRows.value=[];tableRef.value?.clearSelection()}
function resetFilters(){keyword.value='';status.value='';categoryFilter.value='';priceMin.value='';priceMax.value='';dateFrom.value='';dateTo.value='';page.value=1;clearSelection()}
async function batchProducts(action){if(!selectedRows.value.length)return;const ids=selectedRows.value.map(x=>x.id);const body={ids,action};if(['addGroup','removeGroup'].includes(action)){const group=await prompt('填写分组名称（如：特色项目），多个商品将统一处理。','商品分组');if(group===null)return;body.group=group}else if(action==='memberPrice'){const value=await prompt('填写统一会员价（元）。','批量设置会员价');if(value===null)return;body.memberPrice=Number(value);if(!Number.isFinite(body.memberPrice)||body.memberPrice<0)return ElMessage.warning('请输入有效的非负会员价')}else if(action==='freeShipping'){body.value=await confirm('选中的商品都设置为包邮吗？','批量设置包邮')}if(!await confirm('将对 '+ids.length+' 件商品执行批量操作，确定继续吗？'))return;try{await request({url:'/anqi/products/batch',method:'post',data:body});ElMessage.success('已处理 '+ids.length+' 件商品');clearSelection();await load()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'批量操作失败')}}

function edit(row){advanced.value=false;form.value=row?JSON.parse(JSON.stringify(row)):{enabled:false,status:'draft',kind:'service',categoryId:'category-featured',price:0,stock:0,sold:0,home:false,recommended:false,hot:false,isNew:false,gift:false,trial:false,sort:1,keywords:[],keywordsText:'',gallery:[],skus:[]};form.value.keywordsText=Array.isArray(form.value.keywords)?form.value.keywords.join(' '):(form.value.keywords||'');if(!Array.isArray(form.value.gallery))form.value.gallery=[];if(!Array.isArray(form.value.skus))form.value.skus=[];form.value.skus.forEach(s=>{s.attributesText=Object.entries(s.attributes||{}).map(([k,v])=>k+':'+v).join(',')});if(resource.value==='stores'){form.value.appointmentDurationMinutes??=60;form.value.schedulingEnabled??=false}courseEnabled.value=row?.coursePrice!=null;dialog.value=true}
function editModule(row){moduleForm.value=row?JSON.parse(JSON.stringify(row)):{type:'banner',title:'',subtitle:'',image:'',sort:(homeModules.value.length||0)+1,enabled:true,publishStatus:'draft',targetType:'',targetId:'',description:''};if(!moduleForm.value.publishStatus)moduleForm.value.publishStatus='published';moduleDialog.value=true}
function moduleTypeLabel(value){return ({banner:'Banner',category:'分类入口',product:'推荐商品',activity:'活动入口',store:'门店入口',notice:'公告/图文'}[value]||value)}
async function loadHomeModules(){try{const r=await request({url:'/anqi/homeModules'});homeModules.value=Array.isArray(r.data)?r.data:[]}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'首页模块加载失败')}}
async function loadAssets(){try{const r=await request({url:'/anqi/assets'});assets.value=Array.isArray(r.data)?r.data:[]}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'图片列表加载失败')}}
async function removeAsset(row){if(!await confirm('删除后图片文件无法恢复，确定删除“'+(row.originalName||'此图片')+'”？'))return;try{await request({url:'/anqi/assets/'+encodeURIComponent(row.id),method:'delete'});ElMessage.success('图片已删除');await loadAssets()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'图片正在使用中，无法删除')}}
async function saveModule(){if(!String(moduleForm.value.title||'').trim()||!String(moduleForm.value.image||'').trim())return ElMessage.warning('请填写标题并上传图片');moduleSaving.value=true;try{await request({url:'/anqi/homeModules'+(moduleForm.value.id?'/'+moduleForm.value.id:''),method:moduleForm.value.id?'put':'post',data:moduleForm.value});ElMessage.success('首页模块已保存');moduleDialog.value=false;await loadHomeModules()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'保存失败，已保留填写内容')}finally{moduleSaving.value=false}}
async function toggleModule(row){try{await request({url:'/anqi/homeModules/'+row.id,method:'put',data:{enabled:row.enabled===false}});await loadHomeModules();ElMessage.success('首页模块状态已更新')}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'更新失败')}}
async function removeModule(row){if(!await confirm('删除首页模块后无法恢复，确定继续吗？'))return;try{await request({url:'/anqi/homeModules/'+row.id,method:'delete'});await loadHomeModules();ElMessage.success('首页模块已删除')}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'删除失败')}}
function resetCategory(){categoryForm.value={name:'',sort:(refs.value.categories||[]).length+1,enabled:true}}
function editCategory(row){categoryForm.value={...row}}
async function saveCategory(){if(!String(categoryForm.value.name||'').trim())return ElMessage.warning('请填写分类名称');categorySaving.value=true;try{const body={name:String(categoryForm.value.name).trim(),sort:Number(categoryForm.value.sort||0),enabled:categoryForm.value.enabled!==false};await request({url:'/anqi/categories'+(categoryForm.value.id?'/'+categoryForm.value.id:''),method:categoryForm.value.id?'put':'post',data:body});ElMessage.success('分类已保存');await loadCategories();resetCategory()}catch{}finally{categorySaving.value=false}}
async function loadCategories(){try{const r=await request({url:'/anqi/categories'});refs.value.categories=r.data||[]}catch{ElMessage.error('分类加载失败，请刷新重试')}}
async function toggleCategory(row){await updateCategory(row,{enabled:row.enabled===false})}
async function updateCategory(row,changes){try{await request({url:'/anqi/categories/'+row.id,method:'put',data:changes});ElMessage.success('分类已更新');await loadCategories()}catch{}}
async function removeCategory(row){if(!await confirm('删除分类后，商品不会删除，但会显示为未分类。确定继续吗？'))return;try{await request({url:'/anqi/categories/'+row.id,method:'delete'});ElMessage.success('分类已删除');if(categoryForm.value.id===row.id)resetCategory();await loadCategories();await load()}catch{}}
async function save(){if(resource.value==='products'){for(let i=0;i<(form.value.skus||[]).length;i++){const sku=form.value.skus[i];if(!String(sku.name||'').trim())return ElMessage.warning('第'+(i+1)+'个 SKU：请填写规格名称');if(!Number.isFinite(Number(sku.price))||Number(sku.price)<0)return ElMessage.warning('第'+(i+1)+'个 SKU：价格必须是有效非负数字');if(!Number.isInteger(Number(sku.stock))||Number(sku.stock)<0)return ElMessage.warning('第'+(i+1)+'个 SKU：库存必须是非负整数');const attrs=String(sku.attributesText||'').trim();if(attrs&&attrs.split(/[,，]/).some(v=>!/^\s*[^:：]+[:：].+$/.test(v)))return ElMessage.warning('第'+(i+1)+'个 SKU：属性请按“颜色:白,容量:30ml”填写')}}for(const f of shownFields.value)if(f.required&&!((resource.value==='products'&&form.value.skus?.length&&['price','stock'].includes(f.key)))&&!String(form.value[f.key]??'').trim())return ElMessage.warning('请填写'+fieldLabel(f));if(resource.value==='products'){if(form.value.kind==='service'&&courseEnabled.value&&form.value.coursePrice==null)return ElMessage.warning('请填写疗程价格');form.value.coursePrice=form.value.kind==='service'&&courseEnabled.value?form.value.coursePrice:null;form.value.keywords=String(form.value.keywordsText||'').split(/[,，\s]+/).map(v=>v.trim()).filter(Boolean);delete form.value.keywordsText;form.value.skus=(form.value.skus||[]).map(s=>{const attributes=Object.fromEntries(String(s.attributesText||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean).map(v=>{const i=v.indexOf(':');return i>0?[v.slice(0,i).trim(),v.slice(i+1).trim()]:['', '']}).filter(([k,v])=>k&&v));const next={...s,attributes};delete next.attributesText;return next});if(form.value.status==='published')form.value.enabled=true;else if(form.value.status)form.value.enabled=false;}saving.value=true;try{await request({url:endpoint()+(form.value.id?'/'+form.value.id:''),method:form.value.id?'put':'post',data:form.value});dialog.value=false;ElMessage.success('已保存');await load()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'保存失败，已保留当前内容')}finally{saving.value=false}}
async function saveConfig(){if(data.value.appointmentCapacity!==undefined&&(!Number.isInteger(Number(data.value.appointmentCapacity))||Number(data.value.appointmentCapacity)<1))return ElMessage.warning('每个预约时段可接待人数必须是正整数');if(data.value.appointmentTimes!==undefined&&String(data.value.appointmentTimes).split(',').map(v=>v.trim()).filter(Boolean).some(v=>!/^[0-9]{2}:[0-9]{2}$/.test(v)))return ElMessage.warning('预约时间请按 HH:MM 格式，并用逗号分隔');saving.value=true;try{await request({url:endpoint(),method:'put',data:data.value});ElMessage.success('已保存，顾客重新打开页面即可看到修改')}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'保存失败，已保留当前内容')}finally{saving.value=false}}
async function confirm(message,title='请确认'){try{await ElMessageBox.confirm(message,title,{confirmButtonText:'确认',cancelButtonText:'返回',type:'warning'});return true}catch{return false}}
async function remove(row){if(!await confirm('确定删除“'+row.name+'”？删除后无法恢复。'))return;try{await request({url:endpoint()+'/'+row.id,method:'delete'});ElMessage.success('已删除');await load()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'删除失败')}}
function copyRow(row){const clone=JSON.parse(JSON.stringify(row));delete clone.id;clone.name=(clone.name||'商品')+'（复制）';clone.title=(clone.title||'模块')+'（复制）';clone.status='draft';clone.enabled=false;if(resource.value==='products')edit(clone);else if(resource.value==='homeModules')editModule(clone)}
async function update(row,changes){try{await request({url:endpoint()+'/'+row.id,method:'put',data:changes});ElMessage.success('已更新');await load()}catch{}}
async function setStatus(row,value){const message=value==='cancelled'?'确认取消这次预约？':resource.value==='appointments'?(row.entitlementId?'确认本次服务已完成？仅扣减此项目 1 次，其他项目仍可预约。':'确认顾客已完成服务？对应订单也会同步完成。'):resource.value==='claims'?'确认已将商品交给顾客？':'确认服务或商品已经交付给顾客？';if(await confirm(message))await update(row,{status:value})}
async function prompt(message,title,password=false){try{return (await ElMessageBox.prompt(message,title,{confirmButtonText:'确定',cancelButtonText:'返回',inputType:password?'password':'text',inputValidator:v=>!!v?.trim()||'请填写内容'})).value}catch{return null}}
async function orderAction(row,action){const body={action};if(action==='confirmPayment'){const note=await prompt('请核实实际收到 ¥'+Number(row.total).toFixed(2)+'，填写收款方式或凭证说明。','确认已收到顾客付款');if(note===null)return;body.note=note}else if(action==='ship'){const tracking=await prompt('填写快递单号，或填写到店领取的说明。','填写发货信息');if(tracking===null)return;body.tracking=tracking}else if(action==='refund'){const note=await prompt('填写退款原因或处理说明，库存会按规则恢复。','确认售后退款');if(note===null)return;body.note=note}else if(!await confirm('取消这笔未付款订单后，商品数量会自动恢复。'))return;try{await request({url:endpoint()+'/'+row.id,method:'post',data:body});ElMessage.success(action==='refund'?'退款已登记，库存已恢复':'订单已更新');await load()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'订单操作失败')}}
async function memberMore(row,cmd){if(cmd==='password')return memberAction(row,'resetPassword');if(cmd==='points')return memberPoints(row);if(cmd==='gift'){if(await confirm(row.invited?'取消后，该会员不能领取新客礼品。':'允许该会员领取一次新客礼品？'))await update(row,{invited:!row.invited})}else if(await confirm(row.disabled?'恢复后，该会员可以正常登录。':'停用后，该会员无法登录，已有记录会保留。'))await update(row,{disabled:!row.disabled})}
async function memberAction(row,action){const password=await prompt('请输入8至72位的新密码。','重置会员登录密码',true);if(password===null)return;try{await request({url:endpoint()+'/'+row.id,method:'post',data:{action:'resetPassword',password}});ElMessage.success('已更新会员信息');await load()}catch{}}
async function memberPoints(row){const value=await prompt('输入本次积分变动，增加请输入正数，扣减请输入负数。','调整 '+(row.name||'会员')+' 的积分');if(value===null)return;const amount=Number(value);if(!Number.isInteger(amount)||amount===0)return ElMessage.warning('请输入非零整数积分');const note=await prompt('填写积分变动原因。','积分变动原因');if(note===null)return;try{await request({url:endpoint()+'/'+row.id,method:'post',data:{action:'points',amount,note}});ElMessage.success('积分已更新');await load()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'积分更新失败')}}
async function prepareImage(file){if(file.size>5*1024*1024)throw new Error('图片过大，请选择小于5兆的图片');const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('图片无法读取，请更换图片'));img.src=source});if(image.width<100||image.height<100)throw new Error('图片尺寸过小，至少需要 100×100 像素');const max=2000;const scale=Math.min(1,max/image.width,max/image.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.86);return {data,width:image.width,height:image.height}}
function pickImage(target,key){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{const file=input.files[0];if(!file)return;uploading.value=true;try{const content=await prepareImage(file);const r=await request({url:'/anqi/upload',method:'post',data:{data:content.data,name:file.name,width:content.width,height:content.height}});target[key]=r.data.url;ElMessage.success('图片已处理并上传，点击保存后生效')}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'图片上传失败，请重试')}finally{uploading.value=false}};input.click()}
function pickImages(target,key){const input=document.createElement('input');input.multiple=true;input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{const files=Array.from(input.files||[]);if(!files.length)return;uploading.value=true;try{for(const file of files){const content=await prepareImage(file);const r=await request({url:'/anqi/upload',method:'post',data:{data:content.data,name:file.name,width:content.width,height:content.height}});target[key]=[...(target[key]||[]),r.data.url]}ElMessage.success('图片已处理并上传，保存后生效')}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'图片上传失败，请重试')}finally{uploading.value=false}};input.click()}
function openInventory(row){inventoryProduct.value=JSON.parse(JSON.stringify(row));inventoryForm.value={productId:row.id,skuId:row.skus?.length===1?row.skus[0].id:'',delta:0,reason:''};inventoryDialog.value=true}
async function saveInventory(){if(!inventoryForm.value.delta||!Number.isInteger(Number(inventoryForm.value.delta)))return ElMessage.warning('请输入非零整数库存变动');if(!String(inventoryForm.value.reason||'').trim())return ElMessage.warning('请填写库存调整原因');inventorySaving.value=true;try{await request({url:'/anqi/products/'+inventoryForm.value.productId,method:'post',data:{action:'adjustStock',skuId:inventoryForm.value.skuId,delta:Number(inventoryForm.value.delta),reason:inventoryForm.value.reason}});ElMessage.success('库存已更新并记录流水');inventoryDialog.value=false;await load()}catch(e){ElMessage.error(e?.response?.data?.msg||e?.message||'库存调整失败')}finally{inventorySaving.value=false}}
function removeGallery(index){form.value.gallery.splice(index,1)}
function addSku(){form.value.skus.push({id:'sku-'+Date.now(),name:'',code:'',attributes:{},attributesText:'',price:Number(form.value.price||0),stock:0,image:'',enabled:true})}
function removeSku(index){form.value.skus.splice(index,1)}
function exportCsv(){const safe=value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\ufeff'+[columns.value.map(c=>safe(c.label)).join(','),...filtered.value.map(row=>columns.value.map(c=>safe(display(row,c.key))).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=meta.value.title+'.csv';a.click();URL.revokeObjectURL(url)}</script>
